// Current-product synthetic regressions for the six PR #85 CAB/IR gaps.
// Generated bytes only: filenames are historical lookup traps, never captures.
#include "PluginProcessor.h"
#include "FactoryPresets.h"
#include "OriginalCabParameters.h"
#include "IRCollection.h"
#include <bit>
#include <iostream>
#include <limits>
#include <map>
#include <stdexcept>
#include <vector>

namespace {
void require(bool ok,const char* message) {if(!ok)throw std::runtime_error(message);}
struct Folder {
    juce::File path;
    explicit Folder(const juce::File& parent):path(parent.getNonexistentChildFile("cab-ir-acceptance",{},false)) {
        require(path.createDirectory().wasOk(),"Cannot create owned fixture directory");
    }
    ~Folder(){path.deleteRecursively();}
};
void set(ChimeraProcessor& p,const juce::String& id,float value) {
    auto* parameter=p.parameters().getParameter(id);require(parameter!=nullptr,"Unknown fixture parameter");
    parameter->setValueNotifyingHost(parameter->convertTo0to1(value));
}
float value(ChimeraProcessor& p,const juce::String& id) {
    auto* raw=p.parameters().getRawParameterValue(id);require(raw!=nullptr,"Missing CAB parameter");return raw->load();
}
std::map<juce::String,float> parameters(ChimeraProcessor& p) {
    std::map<juce::String,float> result;
    for(auto* raw:p.getParameters())if(auto* parameter=dynamic_cast<juce::RangedAudioParameter*>(raw))
        result[parameter->paramID]=parameter->getValue();
    return result;
}
juce::MemoryBlock state(ChimeraProcessor& p) {
    juce::MemoryBlock bytes;require(p.tryGetStateInformation(bytes),"State serialization failed");return bytes;
}
// IEEE float WAV written byte-for-byte, bypassing any writer's NaN sanitization.
juce::MemoryBlock wav(int rate=48000,int channels=1,int frames=2048,float exceptional=.25f,
                       int exceptionalFrame=0,int exceptionalChannel=0,size_t paddedSize=0,bool silent=false) {
    juce::MemoryOutputStream out;
    const int dataBytes=channels*frames*4;
    const size_t size=paddedSize?paddedSize:size_t(44+dataBytes);
    require(size>=size_t(44+dataBytes),"Invalid padding fixture");
    out.write("RIFF",4);out.writeInt(int(size-8));out.write("WAVEfmt ",8);out.writeInt(16);
    out.writeShort(3);out.writeShort(short(channels));out.writeInt(rate);out.writeInt(rate*channels*4);
    out.writeShort(short(channels*4));out.writeShort(32);out.write("data",4);out.writeInt(dataBytes);
    for(int frame=0;frame<frames;++frame)for(int channel=0;channel<channels;++channel) {
        float x=silent?0.f:frame==0?.25f:0.f;
        if(!silent && frame==exceptionalFrame && channel==exceptionalChannel)x=exceptional;
        out.writeInt(std::bit_cast<int>(x));
    }
    if(size>out.getDataSize()) {
        require(size>=out.getDataSize()+8,"Padding chunk too short");
        const auto padding=size-out.getDataSize()-8;
        out.write("JUNK",4);out.writeInt(int(padding));out.writeRepeatedByte(0,padding);
    }
    return out.getMemoryBlock();
}
void write(const juce::File& file,const juce::MemoryBlock& bytes) {
    require(file.replaceWithData(bytes.getData(),bytes.getSize()),"Cannot write synthetic IR");
}
void input(juce::AudioBuffer<float>& b,int block) {
    for(int n=0;n<b.getNumSamples();++n) {
        const float x=.1f*std::sin(float((block*b.getNumSamples()+n)*.017));
        b.setSample(0,n,x);b.setSample(1,n,-.7f*x);
    }
}
void equalAudio(const std::vector<float>& a,const std::vector<float>& b) {
    require(a.size()==b.size(),"Audio shape changed");double energy=0;
    for(size_t n=0;n<a.size();++n) {
        require(std::isfinite(a[n]) && std::isfinite(b[n]),"Nonfinite output");
        require(std::abs(a[n]-b[n])<=1.e-7f,"Last good audio changed");energy+=double(a[n])*a[n];
    }
    require(energy>1.e-8,"Vacuous silent audio comparison");
}
std::vector<float> render(ChimeraProcessor& p) {
    p.prepareToPlay(48000,128);juce::AudioBuffer<float> b(2,128);juce::MidiBuffer midi;std::vector<float> output;
    for(int block=0;block<64;++block) {
        input(b,block);p.processBlock(b,midi);
        for(int c=0;c<2;++c)for(int n=0;n<128;++n)output.push_back(b.getSample(c,n));
    }
    spectralforge::OriginalCabParameters modeled;modeled.bind(p.parameters());
    for(int lane=0;lane<3;++lane)for(int slot=0;slot<2;++slot) {
        const auto key=modeled.read(lane,slot);
        require(p.micDisplayRevision(lane,slot)[2]==(uint64_t{1}|(key<<4)),
            "Production audio did not install the factory modeled request");
    }
    p.releaseResources();return output;
}
void factoryRecipe(ChimeraProcessor& p,int index) {
    using namespace spectralforge;
    // Independent ordinals from the accepted ledger/catalog, not the recipe under test.
    constexpr int recipes[3][3][3]={{{9,14,5},{7,9,2},{3,7,1}},{{6,10,5},{6,12,3},{3,7,1}},{{7,9,5},{7,9,2},{3,2,1}}};
    require(value(p,"mode")==2,"Signature must be Matrix");
    OriginalCabParameters modeled;modeled.bind(p.parameters());
    for(int lane=0;lane<3;++lane) {
        const auto suffix=juce::String(lane+1);const auto& expected=recipes[index-31][lane];
        require(juce::String(presetIRTarget(index,lane)).isEmpty() && juce::String(presetIRTargetHash(index,lane)).isEmpty(),"Factory private target/hash revived");
        require(value(p,"cab"+suffix)==1 && value(p,"cabtype"+suffix)==0 && value(p,"cabBtype"+suffix)==0 && value(p,"cabblend"+suffix)==0,"Factory recall selected capture or disabled CAB");
        require(value(p,cabLayoutID(lane,"layout"))==expected[0] && value(p,cabExpansionID(lane,"driver"))==expected[1]
            && value(p,cabExpansionID(lane,"Amic"))==expected[2],"Accepted modeled recipe changed");
        const auto& enclosure=cabLayout::layouts[size_t(expected[0]-1)];const auto& driver=cabExpansion::drivers[size_t(expected[1]-1)];
        require(enclosure.bass==driver.bass && enclosure.inches==driver.inches,"Incompatible modeled driver/layout");
        for(int slot=0;slot<2;++slot) {
            require(p.micName(lane,slot).isEmpty(),"Factory recall loaded a user file");
            require((modeled.read(lane,slot)!=0)==(slot==0),"Modeled mic enable changed");
        }
    }
}
void factoryNegatives(const juce::File& source) {
    using C=spectralforge::IRCollection;
    // Only create/remove our unique child. Do not rewrite ir-folders/library preferences.
    const auto before=C::scan(C::roots(),false);
    require(before.empty(),"Factory negative fixture needs a clean CI user IR library; existing files kept");
    Folder library(C::userRoot().getChildFile("IRs"));
    const auto catalog=juce::JSON::parse(source.getChildFile("docs/reference/ir-catalog.json"));
    require(catalog.isArray() && catalog.getArray()->size()>0,"Historical filename inventory missing");
    std::array<std::map<juce::String,float>,3> baseline;
    std::array<std::vector<float>,3> audio;
    for(int phase=0;phase<3;++phase) {
        if(phase)for(const auto& entry:*catalog.getArray()) {
            const auto name=entry["file"].toString();require(name==juce::File::createLegalFileName(name),"Unsafe historical fixture filename");
            const auto file=library.path.getChildFile(name);
            write(file,phase==1?wav():juce::MemoryBlock(64,true));
            require(!C::matchesExpectedHash(file,entry["sha256"].toString()),"Synthetic trap accidentally matches private hash");
        }
        const auto visible=C::scan(C::roots(),false);
        require(visible.size()==size_t(phase?catalog.getArray()->size():0),"Negative fixtures not visible in production roots");
        for(const auto& entry:visible)require(entry.ready()==(phase==1),"Fixture validity differs from intended library phase");
        for(int song=0;song<3;++song) {
            auto p=std::make_unique<ChimeraProcessor>();p->loadFactoryPreset(31+song);factoryRecipe(*p,31+song);
            const auto values=parameters(*p);const auto rendered=render(*p);factoryRecipe(*p,31+song);
            if(phase==0){baseline[size_t(song)]=values;audio[size_t(song)]=rendered;}
            else {require(parameters(*p)==baseline[size_t(song)],"Library presence changed factory state");equalAudio(audio[size_t(song)],rendered);}
            std::cout<<"CASE factory preset="<<31+song<<" phase="<<phase<<" files="<<visible.size()<<" PASS\n";
        }
    }
    std::cout<<"PASS CAB_IR A2.07 A5.01 A6.01 factory_absent_valid_corrupt\n";
}
void boundaryTests() {
    using C=spectralforge::IRCollection;
    Folder temp(juce::File::getSpecialLocation(juce::File::tempDirectory));
    struct Case {const char* name;juce::MemoryBlock bytes;bool accepted;};
    const float nan=std::numeric_limits<float>::quiet_NaN(),inf=std::numeric_limits<float>::infinity();
    const std::vector<Case> cases{
        {"mono_min_rate_min_frames",wav(8000,1,8),true},
        {"stereo_max_rate_one_second",wav(384000,2,384000),true},
        {"raw_exact_4MiB",wav(48000,1,8,.25f,0,0,4*1024*1024),true},
        {"positive_sample_limit",wav(48000,1,8,32.f),true},
        {"negative_sample_limit",wav(48000,1,8,-32.f),true},
        {"raw_over_4MiB",wav(48000,1,8,.25f,0,0,4*1024*1024+2),false},
        {"raw_under_header",juce::MemoryBlock(43,true),false},
        {"corrupt",juce::MemoryBlock(64,true),false},
        {"silent",wav(48000,1,8,0,0,0,0,true),false},
        {"rate_below",wav(7999,1,8),false}, {"rate_above",wav(384001,1,8),false},
        {"zero_channels",wav(48000,0,8),false}, {"three_channels",wav(48000,3,8),false},
        {"short_frames",wav(48000,1,7),false}, {"over_one_second",wav(8000,1,8001),false},
        {"nan_late_right",wav(48000,2,2048,nan,1025,1),false},
        {"positive_inf_late_right",wav(48000,2,2048,inf,1025,1),false},
        {"negative_inf_late_right",wav(48000,2,2048,-inf,1025,1),false},
        {"sample_over_positive",wav(48000,1,8,std::nextafter(32.f,inf)),false},
        {"sample_over_negative",wav(48000,1,8,std::nextafter(-32.f,-inf)),false}
    };
    for(const auto& c:cases) {
        const auto file=temp.path.getChildFile(juce::String(c.name)+".wav");write(file,c.bytes);
        juce::String error;const auto decoded=spectralforge::IRLibrary::decode(c.bytes,file.getFileName(),error);
        require(bool(decoded)==c.accepted && error.isEmpty()==c.accepted,"Loader boundary result mismatch");
        require(C::validateFile(file).isEmpty()==c.accepted,"File validator boundary mismatch");
        require(C::validateEncodedIR(c.bytes).isEmpty()==c.accepted,"Embedded validator boundary mismatch");
        const auto entries=C::scan({temp.path},false,nullptr,temp.path.getChildFile("preferences.json"));
        auto found=std::find_if(entries.begin(),entries.end(),[&](const auto& e){return e.file==file;});
        require(found!=entries.end() && found->ready()==c.accepted,"Invalid IR marked loadable or positive control rejected");
        std::cout<<"CASE boundary "<<c.name<<" accepted="<<c.accepted<<" bytes="<<c.bytes.getSize()<<" PASS\n";
        require(file.deleteFile(),"Cannot remove owned boundary fixture");
    }
    std::cout<<"PASS CAB_IR A5.05 A6.05 boundaries_20\n";
}
void preservationTests() {
    using namespace spectralforge;
    Folder temp(juce::File::getSpecialLocation(juce::File::tempDirectory));
    const auto good=temp.path.getChildFile("good.wav");const auto bytes=wav();write(good,bytes);
    const auto missing=temp.path.getChildFile("missing.wav"),corrupt=temp.path.getChildFile("corrupt.wav"),silent=temp.path.getChildFile("silent.wav");
    write(corrupt,juce::MemoryBlock(64,true));write(silent,wav(48000,1,2048,0,0,0,0,true));
    auto control=std::make_unique<ChimeraProcessor>(),candidate=std::make_unique<ChimeraProcessor>();
    for(auto* p:{control.get(),candidate.get()}) {
        set(*p,"mode",2);set(*p,"oversampling",0);set(*p,"lowampmix",1);set(*p,"lowcomp",0);
        for(const auto* id:{"gateon","transposeon","tuneron","boardEnabled","doubleron","metronome"})set(*p,id,0);
        for(const auto& spec:fxSpecs)if(spec.toggle)set(*p,spec.id,0);
        for(int section=0;section<3;++section)set(*p,postNativeModeID(section),0);
        for(int lane=0;lane<3;++lane) {
            const auto n=juce::String(lane+1);set(*p,"ampon"+n,0);set(*p,"cab"+n,1);set(*p,"cabblend"+n,.5f);
            for(int slot=0;slot<2;++slot)require(p->loadMicIR(lane,slot,good).wasOk(),"Cannot establish good six-slot IR state");
        }
        p->prepareToPlay(48000,128);
    }
    int offset=0;
    const auto compare=[&](int blocks) {
        std::vector<float> a,b;juce::AudioBuffer<float> x(2,128),y(2,128);juce::MidiBuffer midi;
        for(int n=0;n<blocks;++n,++offset) {
            input(x,offset);y.makeCopyOf(x);control->processBlock(x,midi);candidate->processBlock(y,midi);
            for(int c=0;c<2;++c)for(int i=0;i<128;++i){a.push_back(x.getSample(c,i));b.push_back(y.getSample(c,i));}
            // Give the actual worker time to publish any erroneous replacement;
            // this sleep is in the test driver, never inside processBlock.
            juce::Thread::sleep(1);
        }
        equalAudio(a,b);
    };
    compare(64);
    const auto saved=state(*candidate);const auto values=parameters(*candidate);
    for(int lane=0;lane<3;++lane)for(int slot=0;slot<2;++slot)for(const auto& file:{missing,corrupt,silent}) {
        const auto generation=candidate->micDisplayRevision(lane,slot)[3];
        const auto result=candidate->loadMicIR(lane,slot,file);
        require(result.failed() && result.getErrorMessage().isNotEmpty(),"Bad IR load accepted or has no reason");
        require(candidate->micStatus(lane,slot).contains(result.getErrorMessage()),"Rejected load not visible in status");
        require(candidate->micName(lane,slot)==good.getFileName(),"Failed load replaced last good identity");
        require(state(*candidate)==saved && parameters(*candidate)==values,"Failed load changed binary state or host parameters");
        compare(64);
        require(candidate->micDisplayRevision(lane,slot)[3]==generation,"Failed load published a new kernel");
        require(state(*candidate)==saved,"Worker changed saved state after rejected load");
        std::cout<<"CASE preserve lane="<<lane<<" mic="<<slot<<" rejected="<<file.getFileName()<<" PASS\n";
    }
    control->releaseResources();candidate->releaseResources();
    juce::MemoryBlock retained;require(good.loadFileAsData(retained) && retained==bytes,"Original personal IR bytes modified");
    const auto entries=IRCollection::scan({temp.path},false,nullptr,temp.path.getChildFile("preferences.json"));
    for(const auto& entry:entries)require(entry.ready()==(entry.file==good),"Broken personal file is ready");
    require(std::none_of(entries.begin(),entries.end(),[&](const auto& e){return e.file==missing;}),"Missing file became a library entry");
    std::cout<<"PASS CAB_IR A8.02 rejected_load_preserves_six_slots_18\n";
}
}
int main(int argc,char** argv) {
    juce::ScopedJuceInitialiser_GUI init;
    try {
        require(argc==3,"Usage: ChimeraCabIRAcceptanceTests factory|boundaries|preservation SOURCE_ROOT");
        const std::string mode=argv[1];
        if(mode=="factory")factoryNegatives(juce::File(argv[2]));
        else if(mode=="boundaries")boundaryTests();
        else if(mode=="preservation")preservationTests();
        else throw std::runtime_error("Unknown suite; no checks executed");
        return 0;
    } catch(const std::exception& e){std::cerr<<"FAIL CAB_IR "<<e.what()<<'\n';return 1;}
}
